def _pull_missing_outputs(self) -> None:
    """Pull missing outputs for this stage when --pull is specified."""
    from dvc.output import OutputDoesNotExistError
    from dvc.exceptions import CheckoutError

    # Check if any outputs are missing and try to pull them
    missing_outputs = [out for out in self.outs if not out.exists]
    if missing_outputs:
        # For each missing output, attempt to pull it from remote storage
        for out in missing_outputs:
